// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const app = express();

// Security Middleware
app.use(helmet()); // Sets various HTTP headers for security

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use('/users', limiter); // Apply rate limiting to /users endpoint

// Input validation middleware (simplified example)
const validateIdParam = (req, res, next) => {
  const id = req.params.id;
  if (!id || !/^[0-9]+$/.test(id)) {
    return res.status(400).json({ error: 'Invalid user ID format' });
  }
  next();
};

// Enhanced /users endpoint with parameterized route and validation
app.get('/users', (req, res) => {
  // Simulated database query - in real app, use parameterized queries
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Log request (without sensitive data)
  console.log(`GET /users requested at ${new Date().toISOString()}`);

  res.json(users);
});

// Individual user endpoint with validation
app.get('/users/:id', validateIdParam, (req, res) => {
  const userId = parseInt(req.params.id, 10);

  // Simulated secure database lookup
  const user = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ].find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  // Never expose sensitive data like passwords, API keys, etc.
  res.json({
    id: user.id,
    name: user.name,
    email: user.email
  });
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Something went wrong!' });
});

// Handle 404
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

