"use strict";

// Secure application with protection against common OWASP Top 10 issues
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"]
    }
  },
  hsts: { maxAge: 31536000, includeSubDomains: true, preload: true },
  frameguard: { action: 'deny' },
  referrerPolicy: { policy: 'no-referrer' }
}));

// CORS configuration - only allow specified origins
const allowedOrigins = process.env.ALLOWED_ORIGINS 
  ? process.env.ALLOWED_ORIGINS.split(',') 
  : ['http://localhost:3000'];

app.use(cors({
  origin: function (origin, callback) {
    // Allow requests with no origin (like mobile apps, curl)
    if (!origin) return callback(null, true);
    if (allowedOrigins.indexOf(origin) === -1) {
      const msg = 'The CORS policy for this site does not allow access from the specified origin.';
      return callback(new Error(msg), false);
    }
    return callback(null, true);
  },
  credentials: true
}));

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again after 15 minutes',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false // Disable the X-RateLimit-* headers
});

// Apply rate limiting to all requests
app.use(limiter);

// Parse JSON bodies
app.use(express.json());

// Input validation middleware for user data
const validateUser = [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters'),
  body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Must be a valid email address')
];

// Health check endpoint
app.get('/health', (req, res) => {
  // Never expose detailed system info in production
  res.json({ status: 'ok' });
});

// Users endpoint with potential for ID-based access
app.get('/users', (req, res) => {
  // In a real app, this would query a database
  // For now, return static data with minimal info
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' }
  ];
  res.json(users);
});

// Example of a parameterized route with input validation
// In a real app, this would check authentication and authorization
app.get('/users/:id', 
  // Validate that id is a positive integer
  (req, res, next) => {
    const id = parseInt(req.params.id, 10);
    if (isNaN(id) || id <= 0) {
      return res.status(400).json({ 
        error: 'Invalid user ID format' 
      });
    }
    req.userId = id;
    next();
  },
  (req, res) => {
    // Simulate user lookup
    const user = { id: req.userId, name: 'Alice' }; // In reality, check database
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }
    // Never expose sensitive data like email without proper authorization
    res.json(user);
  }
);

// Example POST endpoint with input validation
app.post('/users', validateUser, (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array() 
    });
  }

  // In a real app, save to database
  // Never return sensitive data in response
  res.status(201).json({ 
    message: 'User created successfully',
    id: 3
  });
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Never expose internal error details to clients
  res.status(500).json({
    error: 'An internal server error occurred'
  });
});

// Handle 404 - This should be last route
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found'
  });
});

// Use environment variable for port, with fallback
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Allowed origins: ${allowedOrigins.join(', ')}`);
});

module.exports = app;

